};

solution.solution.cpp:
#include <algorithm>
#include <deque>
#include <format>
#include <optional>
#include <stdexcept>
#include <string>
#include <string_view>
#include <vector>

std::string colored(std::string_view text, int color, bool bright = false)
{
    if (color < 0 || color > 7) throw std::invalid_argument("color must be 0 to 7");
    return std::format("\x1b[{}{}m{}\x1b[0m", bright ? 9 : 3, color, text);
}

std::string progressLine(int percent, int width)
{
    percent = std::clamp(percent, 0, 100);
    const int filled{ percent * width / 100 };
    return "\x1b[2K\r[" + std::string(static_cast<std::size_t>(filled), '#') + std::string(static_cast<std::size_t>(width - filled), '.')
         + std::format("] {:>3}%", percent);
}

struct Key { int vk; char ch; };

class LineEditor
{
public:
    void press(Key key)
    {
        switch (key.vk)
        {
        case 0x08: if (cursor_ > 0) text_.erase(--cursor_, 1); return;
        case 0x2E: if (cursor_ < text_.size()) text_.erase(cursor_, 1); return;
        case 0x25: if (cursor_ > 0) --cursor_; return;
        case 0x27: if (cursor_ < text_.size()) ++cursor_; return;
        case 0x24: cursor_ = 0; return;
        case 0x23: cursor_ = text_.size(); return;
        case 0x1B: text_.clear(); cursor_ = 0; return;
        case 0x0D:
            finished_.push_back(text_);
            if (!text_.empty()) history_.push_back(text_);
            recall_ = history_.size();
            text_.clear();
            cursor_ = 0;
            return;
        case 0x26:
            if (recall_ > 0) show(history_[--recall_]);
            return;
        case 0x28:
            if (recall_ < history_.size()) ++recall_;
            show(recall_ < history_.size() ? history_[recall_] : std::string{});
            return;
        default:
            if (key.ch >= 32 && key.ch <= 126) text_.insert(cursor_++, 1, key.ch);
        }
    }

    const std::string& text() const { return text_; }
    std::size_t cursor() const { return cursor_; }

    std::optional<std::string> takeLine()
    {
        if (finished_.empty()) return std::nullopt;
        std::string line{ std::move(finished_.front()) };
        finished_.pop_front();
        return line;
    }

private:
    void show(const std::string& line)
    {
        text_ = line;
        cursor_ = text_.size();
    }

    std::string text_;
    std::size_t cursor_{ 0 };
    std::deque<std::string> finished_;
    std::vector<std::string> history_;
    std::size_t recall_{ 0 };
};

unitTests:
const int BACK{ 0x08 }, DEL{ 0x2E }, LEFT{ 0x25 }, RIGHT{ 0x27 }, HOME{ 0x24 }, END{ 0x23 }, ESC{ 0x1B }, ENTER{ 0x0D }, UP{ 0x26 }, DOWN{ 0x28 };
void type(LineEditor& e, std::string_view s) { for (char c : s) e.press({ 0x41, c }); }
TEST("colours") {
    CHECK_EQ(colored("OK", 2), std::string("\x1b[32mOK\x1b[0m"));
    CHECK_EQ(colored("warn", 3, true), std::string("\x1b[93mwarn\x1b[0m"));
    CHECK_EQ(colored("", 0), std::string("\x1b[30m\x1b[0m"));
    CHECK_THROWS_AS(colored("x", 8), std::invalid_argument);
    CHECK_THROWS_AS(colored("x", -1), std::invalid_argument);
}
TEST("progress lines") {
    CHECK_EQ(progressLine(50, 10), std::string("\x1b[2K\r[#####.....]  50%"));
    CHECK_EQ(progressLine(0, 4), std::string("\x1b[2K\r[....]   0%"));
    CHECK_EQ(progressLine(100, 4), std::string("\x1b[2K\r[####] 100%"));
    CHECK_EQ(progressLine(33, 10), std::string("\x1b[2K\r[###.......]  33%"));
    CHECK_EQ(progressLine(150, 3), std::string("\x1b[2K\r[###] 100%"));
    CHECK_EQ(progressLine(-5, 3), std::string("\x1b[2K\r[...]   0%"));
}
TEST("typing and moving") {
    LineEditor e;
    type(e, "helo");
    e.press({ LEFT, 0 });
    type(e, "l");
    CHECK_EQ(e.text(), std::string("hello"));
    CHECK_EQ(e.cursor(), 4u);
    e.press({ HOME, 0 });
    e.press({ DEL, 0 });
    type(e, "H");
    e.press({ END, 0 });
    e.press({ RIGHT, 0 });
    CHECK_EQ(e.text(), std::string("Hello"));
    CHECK_EQ(e.cursor(), 5u);
    e.press({ BACK, 0 });
    e.press({ BACK, 0 });
    CHECK_EQ(e.text(), std::string("Hel"));
    e.press({ HOME, 0 });
    e.press({ BACK, 0 });
    e.press({ LEFT, 0 });
    CHECK_EQ(e.cursor(), 0u);
    e.press({ 0x41, '\t' });
    CHECK_EQ(e.text(), std::string("Hel"));
    e.press({ ESC, 0 });
    CHECK(e.text().empty() && e.cursor() == 0);
}
TEST("finished lines") {
    LineEditor e;
    CHECK(!e.takeLine().has_value());
    type(e, "dir");
    e.press({ ENTER, '\r' });
    e.press({ ENTER, '\r' });
    type(e, "cls");
    e.press({ ENTER, '\r' });
    CHECK(e.text().empty());
    CHECK(e.takeLine() == std::optional<std::string>{ "dir" });
    CHECK(e.takeLine() == std::optional<std::string>{ "" });
    CHECK(e.takeLine() == std::optional<std::string>{ "cls" });
    CHECK(!e.takeLine().has_value());
}
TEST("history") {
    LineEditor e;
    type(e, "one"); e.press({ ENTER, 0 });
    type(e, "two"); e.press({ ENTER, 0 });
    e.press({ UP, 0 });
    CHECK_EQ(e.text(), std::string("two"));
    CHECK_EQ(e.cursor(), 3u);
    e.press({ UP, 0 });
    e.press({ UP, 0 });
    CHECK_EQ(e.text(), std::string("one"));
    e.press({ DOWN, 0 });
    CHECK_EQ(e.text(), std::string("two"));
    e.press({ DOWN, 0 });
    CHECK_EQ(e.text(), std::string(""));
    e.press({ UP, 0 });
    type(e, "!");
    e.press({ ENTER, 0 });
    CHECK(e.takeLine() == std::optional<std::string>{ "one" });
    CHECK(e.takeLine() == std::optional<std::string>{ "two" });
    CHECK(e.takeLine() == std::optional<std::string>{ "two!" });
}

